30	        super(name);
31	        Validate.notNull(publicId);
32	        Validate.notNull(systemId);
33	        attributes()
34	            .add(NameKey, name)
35	            .add(PublicId, publicId)
36	            .add(SystemId, systemId);
37	        updatePubSyskey();
