import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;

public class Probe {
    static int fails = 0;
    static void show(String label, String in) {
        System.out.println("=== " + label + " ===");
        System.out.println("IN : " + in.replace("\n", "\\n"));
        try {
            Document doc = Jsoup.parse(in, "", Parser.xmlParser());
            String out = doc.html();
            System.out.println("OUT: " + out.replace("\n", "\\n"));
            StringBuilder types = new StringBuilder();
            for (Node n : doc.childNodes()) types.append(n.nodeName()).append(' ');
            System.out.println("NODES: " + types);
            String out2 = doc.html();
            if (!out.equals(out2)) { System.out.println("NON-IDEMPOTENT OUTPUT!"); fails++; }
        } catch (Throwable t) {
            System.out.println("THREW: " + t);
            t.printStackTrace(System.out);
            fails++;
        }
        System.out.println();
    }
    public static void main(String[] args) {
        show("empty", "");
        show("decl only", "<?xml version=\"1.0\"?>");
        show("decl only full", "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>");
        show("pi only", "<?mypi do something?>");
        show("decl + pi + root", "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<?pi data?>\n<root/>");
        show("doctype public", "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\"><html/>");
        show("doctype system", "<!DOCTYPE note SYSTEM \"Note.dtd\"><note/>");
        show("doctype internal subset", "<!DOCTYPE note [\n<!ENTITY foo \"bar\">\n]><note/>");
        show("comment positions", "<!--a--><root><!--b--></root><!--c-->");
        show("cdata", "<root><![CDATA[<not a tag> & stuff]]></root>");
        show("cdata boundary ws/quotes", "<r><![CDATA[  \"quoted\"  ]]></r>");
        show("case and ns", "<Foo:Bar xmlns:Foo=\"urn:x\" Foo:Attr=\"1\"/>");
        show("empty elem", "<root><empty></empty><a/></root>");
        show("non-ascii in decl/pi", "<?xml version=\"1.0\"?><?pi däta 日本?><r>é</r>");
        show("decl weird ws", "<?xml\n version='1.0'\n encoding='UTF-8'\n standalone='no' ?><r/>");
        show("doctype ws", "<!DOCTYPE  html\n PUBLIC  \"-//x\"  \"http://x\"><html/>");
        show("pi edge data", "<?pi-target some data with > and <?x?> chars <r/>");
        show("text after pi", "<?pi data?><root>text</root>");
        show("multiple PIs", "<?a 1?><?a 2?><?b 3?><r/>");
        show("malformed fragment", "<root><unclosed>text");
        show("decl then junk", "<?xml version=\"1.0\"?><! strange bogus><r/>");
        show("lt text merge", "<r>a < b & c</r>");
        show("attrs quote", "<r a=\"x?\" b='y?'>z?</r>");
        System.out.println(fails == 0 ? "ALL STABLE" : fails + " issues");
    }
}

