import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.parser.Parser;

public class Probe4 {
    static int fails = 0;
    static void eq(String label, Object actual, Object expected) {
        boolean ok = expected.equals(actual);
        if (!ok) fails++;
        System.out.println((ok ? "OK  " : "FAIL") + " " + label + (ok ? "" : "\n  exp: " + expected + "\n  got: " + actual));
    }
    public static void main(String[] args) {
        // 1. full doc round-trip, order preserved, no html/head/body
        String xml = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n" +
            "<!DOCTYPE note SYSTEM \"Note.dtd\">\n" +
            "<?render mode=\"fast\"?>\n<!--top-->\n" +
            "<note xmlns:x=\"urn:x\" x:Id=\"1\"><to>Alice</to><x:empty/><![CDATA[a < b]]></note>\n<?tail end?>";
        Document doc = Jsoup.parse(xml, "", Parser.xmlParser());
        eq("roundtrip", doc.html(), xml);
        eq("no shell", doc.select("html, head, body").size(), 0);

        // 2. repeated same-kind nodes
        Document dups = Jsoup.parse("<?a 1?><?a 2?><!--c1--><!--c2--><r/>", Parser.xmlParser());
        eq("dups", dups.html(), "<?a 1?><?a 2?><!--c1--><!--c2--><r />");

        // 3. empty element self-close
        eq("selfclose", Jsoup.parse("<r><a/></r>", Parser.xmlParser()).html(), "<r><a /></r>");

        // 4. DOM edits reflected immediately
        Document edit = Jsoup.parse("<?pi v1?><root><a>x</a></root>", Parser.xmlParser());
        ProcessingInstruction pi = (ProcessingInstruction) edit.childNode(0);
        pi.data("v2");
        Element root = edit.expectFirst("root");
        root.appendElement("b").text("y");
        root.expectFirst("a").remove();
        eq("edits", edit.html(), "<?pi v2?><root><b>y</b></root>");
        eq("stable", edit.html(), edit.html());

        // 5. multi-document independence + detached nodes
        Document d1 = Jsoup.parse("<?pi one?><r>1</r>", Parser.xmlParser());
        Document d2 = Jsoup.parse("<?pi two?><r>2</r>", Parser.xmlParser());
        ProcessingInstruction moved = (ProcessingInstruction) d1.childNode(0);
        moved.remove();
        eq("detached", moved.outerHtml(), "<?pi one?>");
        d2.expectFirst("r").appendChild(moved);
        moved.data("three");
        eq("doc1 unaffected", d1.html(), "<r>1</r>");
        eq("doc2 updated", d2.html(), "<?pi two?><r>2<?pi three?></r>");

        // 6. empty / decl-only / pi-only inputs
        eq("empty", Jsoup.parse("", "", Parser.xmlParser()).html(), "");
        eq("decl only", Jsoup.parse("<?xml version=\"1.0\" encoding=\"UTF-8\"?>", "", Parser.xmlParser()).html(),
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
        eq("pi only", Jsoup.parse("<?go now?>", "", Parser.xmlParser()).html(), "<?go now?>");

        // 7. boundary whitespace/quotes/internal subset/non-ascii don't swallow followers
        Document b = Jsoup.parse("<?xml\n version='1.0' ?><!DOCTYPE r [\n<!ENTITY e \"v\">\n]><?pi \"q\" 日?><r/>", Parser.xmlParser());
        eq("boundary nodes", b.childNodes().size(), 4);
        eq("boundary last", b.childNode(3).nodeName(), "r");

        // 8. malformed tolerated, no exception, neighbors not merged
        Document m = Jsoup.parse("<?pi broken", Parser.xmlParser());
        eq("unterminated", m.childNodes().size(), 0);
        Document m2 = Jsoup.parse("<! bogus><r>a</r>", Parser.xmlParser());
        eq("bogus kept", m2.html(), "<!-- bogus--><r>a</r>");

        // 9. HTML mode unchanged
        eq("html pi", Jsoup.parse("<p><?php echo 1; ?></p>").body().html(), "<p><!--?php echo 1; ?--></p>");
        eq("html basic", Jsoup.parse("<p>One<p>Two").body().html(), "<p>One</p>\n<p>Two</p>");

        // 10. doctype public/system preserved
        eq("doctype", Jsoup.parse("<!DOCTYPE h PUBLIC \"-//P\" \"sys\"><h/>", Parser.xmlParser()).childNode(0).outerHtml(),
            "<!DOCTYPE h PUBLIC \"-//P\" \"sys\">");

        // 11. W3C DOM conversion retains PI
        org.w3c.dom.Document w3c = new org.jsoup.helper.W3CDom().fromJsoup(
            Jsoup.parse("<?xml version=\"1.0\"?><?xml-stylesheet href=\"s\"?><root/>", Parser.xmlParser()));
        eq("w3c pi", w3c.getFirstChild().getNodeType(), org.w3c.dom.Node.PROCESSING_INSTRUCTION_NODE);

        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
